    // ---- Reverse Prompt ---------------------------------------------------
    // The load-bearing distinction on this page is provenance. A prompt the
    // FILE recorded is a record of what generated the picture; a prompt an AI
    // produced from the pixels is a guess. The user pastes the result straight
    // into a generator, so a guess wearing the record's label costs them a run
    // they cannot audit. Keep the two claims apart: no inferred string may use
    // the word "record", and no recorded string may hedge.
